using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class BlocksPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Blocks", "View"); return AdminDataService.GetList("Blocks"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Blocks", "View"); return AdminDataService.GetDefinitionMetadata("Blocks"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Blocks", "Delete"); return AdminDataService.Delete("Blocks", id); } } }
